#include <iostream>
#include <string>

int main() {
    std::ios_base::sync_with_stdio(false);
    std::cin.tie(nullptr);

    std::string s;
    std::getline(std::cin, s);

    int size = s.size();
    int middle = (size - 1) / 2;
    bool odd = (size % 2 != 0);

    int i = 0;
    int j = size - 1;
    int counter = 1;

    bool palindrom = true;
    while (true) {
        char begin = s[i];
        char end = s[j];
        if (begin != end) {
            if (counter == 0) {
                palindrom = false;
                break;
            }
            counter--;
        }
        if (i == middle) {
            break;
        }
        i++;
        j--;
    }

    if ((palindrom && counter == 0) || (palindrom && counter == 1 && odd)) {
        std::cout << "YES\n";
    } else {
        std::cout << "NO\n";
    }

    return 0;
}

